class ListNode:
    def __init__(self, value, next=None):
        self.value = value
        self.next = next

class LinkedList:
    def __init__(self):
        self.head = None

    def prepend(self, value):
        self.head = ListNode(value, self.head)

    def __len__(self):
        n = 0
        cur = self.head
        while cur:
            n += 1
            cur = cur.next
        return n

